import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 근태 현황에는 승인된 근태 신청만 반영한다.
// 가정: 월별 집계는 근태 신청의 시작일이 속한 월 기준이다.
// 가정: 개인 조회의 임직원 ID는 현재 사용자 ID와 같다.
const SCOPES = ['전체', '부서', '개인'];
const DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

function textOf(value: unknown): string {
  return value === undefined || value === null ? '' : String(value).trim();
}

function idOf(value: unknown, label: string): string | null {
  const text = textOf(value);
  if (text === '') {
    return null;
  }
  if (!/^\d+$/.test(text)) {
    throw new ApiError(400, 'VALIDATION_FAILED', label + '는 숫자여야 합니다.');
  }
  return text;
}

function isManager(user: ReturnType<typeof currentUser>): boolean {
  try {
    user.require('근태 담당자');
    return true;
  } catch (e) {
    return false;
  }
}

function conditionOf(req: Request) {
  const user = currentUser(req);
  user.require('임직원', '근태 담당자');
  const query = checks.queryOf(req.query) as Record<string, unknown>;
  const startDate = textOf(query['startDate']);
  const endDate = textOf(query['endDate']);
  const scope = textOf(query['scope']);
  if (!DATE_PATTERN.test(startDate) || !DATE_PATTERN.test(endDate)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 시작일과 종료일을 YYYY-MM-DD 형식으로 입력해 주세요.');
  }
  if (!SCOPES.includes(scope)) {
    throw new ApiError(400, 'VALIDATION_FAILED', '조회 범위는 전체, 부서, 개인 중 하나여야 합니다.');
  }
  let departmentId = idOf(query['departmentId'], '부서 ID');
  let employeeId = idOf(query['employeeId'], '임직원 ID');
  if (scope === '개인') {
    departmentId = null;
    employeeId = user.id;
  } else {
    if (!isManager(user)) {
      throw new ApiError(422, 'SCOPE_NOT_PERMITTED', '조회 권한 범위 밖의 요청입니다.');
    }
    if (scope === '부서' && departmentId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '부서 범위 조회는 부서를 선택해야 합니다.');
    }
  }
  const page = Number(textOf(query['page']) || '0');
  const sizeRaw = Number(textOf(query['size']) || '20');
  if (!Number.isInteger(page) || page < 0 || !Number.isInteger(sizeRaw) || sizeRaw < 1) {
    throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호와 크기가 올바르지 않습니다.');
  }
  const size = Math.min(sizeRaw, 200);
  return {
    page,
    size,
    params: {
      startDate,
      endDate,
      departmentId,
      employeeId,
      offset: page * size,
      size,
    },
  };
}

const EMPLOYEE_FILTER = `
  (CAST(:departmentId AS bigint) IS NULL OR employee.department_id = CAST(:departmentId AS bigint))
  AND (CAST(:employeeId AS bigint) IS NULL OR employee.employee_id = CAST(:employeeId AS bigint))`;

const DAILY_FROM = `
  FROM commute_record
  JOIN employee ON employee.employee_id = commute_record.employee_id
  JOIN department ON department.department_id = employee.department_id
  LEFT JOIN attendance_request ON attendance_request.employee_id = commute_record.employee_id
    AND attendance_request.approval_status = '승인'
    AND commute_record.work_date BETWEEN attendance_request.start_date AND attendance_request.end_date
  WHERE commute_record.work_date BETWEEN CAST(:startDate AS date) AND CAST(:endDate AS date)
  AND ${EMPLOYEE_FILTER}`;

const REQUEST_FROM = `
  FROM attendance_request
  JOIN employee ON employee.employee_id = attendance_request.employee_id
  JOIN department ON department.department_id = employee.department_id
  WHERE attendance_request.approval_status = '승인'
  AND attendance_request.start_date <= CAST(:endDate AS date)
  AND attendance_request.end_date >= CAST(:startDate AS date)
  AND ${EMPLOYEE_FILTER}`;

@Controller('api/v1')
export class FnSfr01805Controller {
  @Get('/attendance-status/daily')
  async listDailyAttendanceStatus(@Req() req: Request) {
    const cond = conditionOf(req);
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT employee.name AS "employeeName",
          department.name AS "departmentName",
          commute_record.work_date AS "workDate",
          commute_record.check_in_at AS "checkInAt",
          commute_record.check_out_at AS "checkOutAt",
          attendance_request.attendance_type AS "attendanceType"
        ${DAILY_FROM}
        ORDER BY commute_record.work_date, employee.name, employee.employee_id
        LIMIT :size OFFSET :offset`,
        cond.params,
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" ${DAILY_FROM}`,
        { startDate: cond.params.startDate, endDate: cond.params.endDate, departmentId: cond.params.departmentId, employeeId: cond.params.employeeId },
      );
      return { items, page: cond.page, size: cond.size, total: Number(counts[0]['total']) };
    });
  }

  @Get('/attendance-status/monthly')
  async listMonthlyAttendanceStatus(@Req() req: Request) {
    const cond = conditionOf(req);
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT employee.name AS "employeeName",
          department.name AS "departmentName",
          to_char(attendance_request.start_date, 'YYYY-MM') AS "month",
          SUM(CAST(LEAST(attendance_request.end_date, CAST(:endDate AS date)) - GREATEST(attendance_request.start_date, CAST(:startDate AS date)) + 1 AS integer)) AS "attendanceDays"
        ${REQUEST_FROM}
        GROUP BY employee.employee_id, employee.name, department.name, to_char(attendance_request.start_date, 'YYYY-MM')
        ORDER BY to_char(attendance_request.start_date, 'YYYY-MM'), employee.name, employee.employee_id
        LIMIT :size OFFSET :offset`,
        cond.params,
      );
      const counts = await db.query(
        `SELECT COUNT(DISTINCT (CAST(employee.employee_id AS text) || '-' || to_char(attendance_request.start_date, 'YYYY-MM'))) AS "total"
        ${REQUEST_FROM}`,
        { startDate: cond.params.startDate, endDate: cond.params.endDate, departmentId: cond.params.departmentId, employeeId: cond.params.employeeId },
      );
      return { items, page: cond.page, size: cond.size, total: Number(counts[0]['total']) };
    });
  }

  @Get('/attendance-status/summary')
  async listAttendanceSummary(@Req() req: Request) {
    const cond = conditionOf(req);
    return transaction(async (db) => {
      const items = await db.query(
        `SELECT attendance_request.attendance_type AS "attendanceType",
          COUNT(*) AS "count"
        ${REQUEST_FROM}
        GROUP BY attendance_request.attendance_type
        ORDER BY attendance_request.attendance_type
        LIMIT :size OFFSET :offset`,
        cond.params,
      );
      const counts = await db.query(
        `SELECT COUNT(DISTINCT attendance_request.attendance_type) AS "total"
        ${REQUEST_FROM}`,
        { startDate: cond.params.startDate, endDate: cond.params.endDate, departmentId: cond.params.departmentId, employeeId: cond.params.employeeId },
      );
      return { items, page: cond.page, size: cond.size, total: Number(counts[0]['total']) };
    });
  }
}

