import { useState } from 'react';
import { call, useData, Filters, Band, DataTable, Pager, Select, Field, LookupSelect, DateInput, DateText, Num, ErrorText } from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const VIEWS: [string, string][] = [
  ['daily', '일별 근태 현황'],
  ['monthly', '월별 근태 현황'],
  ['summary', '근태 유형별 집계'],
];

const SCOPES: [string, string][] = [
  ['전체', '전체'],
  ['부서', '부서'],
  ['개인', '개인'],
];

const SIZE = 20;

export default function FnSfr01805Page({ role, notify }: PageProps) {
  const [view, setView] = useState('daily');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [scope, setScope] = useState('개인');
  const [departmentId, setDepartmentId] = useState<number | string>('');
  const [employeeId, setEmployeeId] = useState<number | string>('');
  const [applied, setApplied] = useState<Row | null>(null);
  const [page, setPage] = useState(0);

  const { data, error, loading } = useData<Page | null>(async () => {
    if (applied === null) {
      return null;
    }
    return call<Page>('GET', '/attendance-status/' + view, role, undefined, { ...applied, page, size: SIZE });
  }, [applied, view, page]);

  const search = () => {
    if (startDate === '' || endDate === '') {
      notify('조회 시작일과 종료일을 입력해 주세요.');
      return;
    }
    if (scope === '부서' && departmentId === '') {
      notify('부서 범위로 조회하려면 부서를 선택해 주세요.');
      return;
    }
    setPage(0);
    setApplied({ startDate, endDate, scope, departmentId, employeeId });
  };

  const reset = () => {
    setStartDate('');
    setEndDate('');
    setScope('개인');
    setDepartmentId('');
    setEmployeeId('');
    setPage(0);
    setApplied(null);
  };

  const changeView = (next: string) => {
    setView(next);
    setPage(0);
  };

  const dailyColumns: Column[] = [
    { key: 'employeeName', label: '임직원명' },
    { key: 'departmentName', label: '부서명' },
    { key: 'workDate', label: '근무일자', render: (row) => <DateText value={row['workDate']} /> },
    { key: 'checkInAt', label: '출근시각', render: (row) => <DateText value={row['checkInAt']} time /> },
    { key: 'checkOutAt', label: '퇴근시각', render: (row) => <DateText value={row['checkOutAt']} time /> },
  ];

  const monthlyColumns: Column[] = [
    { key: 'employeeName', label: '임직원명' },
    { key: 'departmentName', label: '부서명' },
    { key: 'month', label: '집계 월' },
    { key: 'attendanceDays', label: '월 근태 일수', render: (row) => <Num value={row['attendanceDays']} /> },
  ];

  const summaryColumns: Column[] = [
    { key: 'attendanceType', label: '근태 유형' },
    { key: 'count', label: '유형별 건수', render: (row) => <Num value={row['count']} /> },
  ];

  const columns = view === 'daily' ? dailyColumns : view === 'monthly' ? monthlyColumns : summaryColumns;
  const rows = data ? data.items : [];
  const emptyText = applied === null ? '조회 조건을 입력하고 조회 버튼을 눌러 주세요.' : '조건에 맞는 근태 내역이 없습니다.';

  return (
    <div className="doc">
      <section className="box">
        <h2>근태 현황 및 집계 조회</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="조회 범위" required>
            <Select value={scope} onChange={setScope} options={SCOPES} placeholder="선택" />
          </Field>
          <Field label="조회 시작일" required>
            <DateInput value={startDate} onChange={setStartDate} />
          </Field>
          <Field label="조회 종료일" required>
            <DateInput value={endDate} onChange={setEndDate} />
          </Field>
          <Field label="부서 ID">
            <LookupSelect table="department" role={role} value={departmentId} onChange={setDepartmentId} placeholder="전체 부서" />
          </Field>
          <Field label="임직원 ID">
            <LookupSelect table="employee" role={role} value={employeeId} onChange={setEmployeeId} placeholder="전체 임직원" />
          </Field>
        </Filters>
      </section>
      <section className="box">
        <Field label="보기">
          <Select value={view} onChange={changeView} options={VIEWS} />
        </Field>
        <Band total={data ? data.total : 0} />
        {error !== '' && <ErrorText text={error} />}
        {loading && <p>불러오는 중입니다.</p>}
        <DataTable columns={columns} rows={rows} empty={emptyText} />
        {data && <Pager page={data.page} size={data.size} total={data.total} onPage={setPage} />}
      </section>
    </div>
  );
}
